parameters.jsCode:
const raw = $('Gmail Trigger').item.json.From || '';
const match = raw.match(/<(.+)>/);
const emailLimpo = match ? match[1].trim().toLowerCase() : raw.trim().toLowerCase();

const mensagem = $('Gmail Trigger').item.json.snippet || '';

const cliente = items[0].json;
const clienteEncontrado = cliente && Object.keys(cliente).length > 0 && cliente.id;

let contextoCliente;
if (clienteEncontrado) {
  contextoCliente = `Cliente cadastrado. Status: ${cliente.status || 'não informado'}. ` +
    `Plano: ${cliente.plano_atual || 'não informado'}. ` +
    `Pagamento: ${cliente.pagamento_status || 'não informado'}.`;
} else {
  contextoCliente = 'Não encontrado na base — é lead novo, nunca foi cliente.';
}

return [{
  json: {
    emailLimpo,
    mensagem,
    contextoCliente
  }
}];
